package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionBuilder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class OptionBuilder_create_TriageGen2Test {

    private String description = "Test description";
    private String longopt = "longOpt";
    private boolean required = true;
    private boolean optionalArg = false;
    private int numberOfArgs = 1;
    private Object type = String.class;
    private char valuesep = ',';
    private String argName = "argName";

    @Before
    public void setUp() {
        OptionBuilder.withLongOpt(longopt)
                     .withDescription(description)
                     .isRequired(required)
                     .withValueSeparator(valuesep)
                     .withArgName(argName)
                     .hasArgs(numberOfArgs)
                     .withType(type);

        if (optionalArg) {
            OptionBuilder.hasOptionalArg();
        }
    }

    @Test
    public void testCreateValidOption() {
        Option option = OptionBuilder.create("opt");
        assertEquals("opt", option.getOpt());
        assertEquals(description, option.getDescription());
        assertEquals(longopt, option.getLongOpt());
        assertEquals(required, option.isRequired());
        assertEquals(optionalArg, option.hasArg());
        assertEquals(numberOfArgs, option.getArgs());
        assertEquals(type, option.getType());
        assertEquals(valuesep, option.getValueSeparator());
        assertEquals(argName, option.getArgName());
    }










}

